CREATE TYPE "Role" AS ENUM ('ADMIN', 'STUDENT');
CREATE TYPE "AccountStatus" AS ENUM ('ACTIVE', 'INACTIVE', 'ARCHIVED');
CREATE TYPE "PublishStatus" AS ENUM ('DRAFT', 'PUBLISHED', 'ARCHIVED');
CREATE TYPE "EnrollmentStatus" AS ENUM ('ACTIVE', 'COMPLETED', 'PAUSED');
CREATE TYPE "Audience" AS ENUM ('ALL', 'ACTIVE_STUDENTS', 'SPECIFIC_STUDENTS');
CREATE TYPE "PhotoPose" AS ENUM ('FRONT', 'SIDE', 'BACK');

CREATE TABLE "User" ("id" UUID NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "Role" NOT NULL DEFAULT 'STUDENT', "status" "AccountStatus" NOT NULL DEFAULT 'ACTIVE', "name" TEXT NOT NULL, "phone" TEXT, "birthDate" DATE, "avatarUrl" TEXT, "lastLoginAt" TIMESTAMP(3), "passwordChangedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StudentProfile" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "objective" TEXT, "notes" TEXT, "initialHeightCm" DECIMAL(5,2), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "StudentProfile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Program" ("id" UUID NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "coverUrl" TEXT, "sortOrder" INTEGER NOT NULL DEFAULT 0, "status" "PublishStatus" NOT NULL DEFAULT 'DRAFT', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Program_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Module" ("id" UUID NOT NULL, "programId" UUID NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "coverUrl" TEXT, "sortOrder" INTEGER NOT NULL DEFAULT 0, "status" "PublishStatus" NOT NULL DEFAULT 'DRAFT', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Module_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Lesson" ("id" UUID NOT NULL, "moduleId" UUID NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "coverUrl" TEXT, "videoUrl" TEXT, "instructions" TEXT, "durationMinutes" INTEGER, "category" TEXT, "sortOrder" INTEGER NOT NULL DEFAULT 0, "status" "PublishStatus" NOT NULL DEFAULT 'DRAFT', "materials" JSONB, "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Lesson_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StudentProgram" ("id" UUID NOT NULL, "studentId" UUID NOT NULL, "programId" UUID NOT NULL, "status" "EnrollmentStatus" NOT NULL DEFAULT 'ACTIVE', "assignedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3), CONSTRAINT "StudentProgram_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LessonProgress" ("id" UUID NOT NULL, "studentId" UUID NOT NULL, "lessonId" UUID NOT NULL, "completed" BOOLEAN NOT NULL DEFAULT false, "completedAt" TIMESTAMP(3), "lastViewedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "LessonProgress_pkey" PRIMARY KEY ("id"));
CREATE TABLE "BodyMeasurement" ("id" UUID NOT NULL, "studentId" UUID NOT NULL, "recordedById" UUID NOT NULL, "measuredAt" DATE NOT NULL, "weightKg" DECIMAL(5,2), "heightCm" DECIMAL(5,2), "bmi" DECIMAL(5,2), "bodyFatPercent" DECIMAL(5,2), "waistCm" DECIMAL(5,2), "abdomenCm" DECIMAL(5,2), "hipsCm" DECIMAL(5,2), "chestCm" DECIMAL(5,2), "rightArmCm" DECIMAL(5,2), "leftArmCm" DECIMAL(5,2), "rightThighCm" DECIMAL(5,2), "leftThighCm" DECIMAL(5,2), "rightCalfCm" DECIMAL(5,2), "leftCalfCm" DECIMAL(5,2), "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "BodyMeasurement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProgressPhoto" ("id" UUID NOT NULL, "studentId" UUID NOT NULL, "photoUrl" TEXT NOT NULL, "pose" "PhotoPose" NOT NULL, "takenAt" DATE NOT NULL, "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ProgressPhoto_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Announcement" ("id" UUID NOT NULL, "createdById" UUID NOT NULL, "title" TEXT NOT NULL, "message" TEXT NOT NULL, "imageUrl" TEXT, "audience" "Audience" NOT NULL DEFAULT 'ALL', "status" "PublishStatus" NOT NULL DEFAULT 'DRAFT', "publishedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Announcement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AnnouncementRecipient" ("announcementId" UUID NOT NULL, "studentId" UUID NOT NULL, CONSTRAINT "AnnouncementRecipient_pkey" PRIMARY KEY ("announcementId", "studentId"));
CREATE TABLE "Notification" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "announcementId" UUID, "title" TEXT NOT NULL, "message" TEXT NOT NULL, "readAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Notification_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RefreshToken" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "tokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "userAgent" TEXT, "ipAddress" TEXT, CONSTRAINT "RefreshToken_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PasswordResetToken" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "tokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "usedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PasswordResetToken_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE INDEX "User_role_status_idx" ON "User"("role", "status"); CREATE INDEX "User_createdAt_idx" ON "User"("createdAt");
CREATE UNIQUE INDEX "StudentProfile_userId_key" ON "StudentProfile"("userId"); CREATE INDEX "StudentProfile_createdAt_idx" ON "StudentProfile"("createdAt");
CREATE INDEX "Program_status_sortOrder_idx" ON "Program"("status", "sortOrder");
CREATE UNIQUE INDEX "Module_programId_sortOrder_key" ON "Module"("programId", "sortOrder"); CREATE INDEX "Module_programId_status_idx" ON "Module"("programId", "status");
CREATE UNIQUE INDEX "Lesson_moduleId_sortOrder_key" ON "Lesson"("moduleId", "sortOrder"); CREATE INDEX "Lesson_moduleId_status_idx" ON "Lesson"("moduleId", "status");
CREATE UNIQUE INDEX "StudentProgram_studentId_programId_key" ON "StudentProgram"("studentId", "programId"); CREATE INDEX "StudentProgram_programId_status_idx" ON "StudentProgram"("programId", "status");
CREATE UNIQUE INDEX "LessonProgress_studentId_lessonId_key" ON "LessonProgress"("studentId", "lessonId"); CREATE INDEX "LessonProgress_studentId_completed_idx" ON "LessonProgress"("studentId", "completed"); CREATE INDEX "LessonProgress_lessonId_completed_idx" ON "LessonProgress"("lessonId", "completed");
CREATE INDEX "BodyMeasurement_studentId_measuredAt_idx" ON "BodyMeasurement"("studentId", "measuredAt" DESC); CREATE INDEX "BodyMeasurement_recordedById_idx" ON "BodyMeasurement"("recordedById");
CREATE INDEX "ProgressPhoto_studentId_takenAt_idx" ON "ProgressPhoto"("studentId", "takenAt" DESC);
CREATE INDEX "Announcement_status_publishedAt_idx" ON "Announcement"("status", "publishedAt" DESC); CREATE INDEX "Announcement_createdById_idx" ON "Announcement"("createdById"); CREATE INDEX "AnnouncementRecipient_studentId_idx" ON "AnnouncementRecipient"("studentId");
CREATE INDEX "Notification_userId_readAt_createdAt_idx" ON "Notification"("userId", "readAt", "createdAt" DESC);
CREATE UNIQUE INDEX "RefreshToken_tokenHash_key" ON "RefreshToken"("tokenHash"); CREATE INDEX "RefreshToken_userId_expiresAt_idx" ON "RefreshToken"("userId", "expiresAt");
CREATE UNIQUE INDEX "PasswordResetToken_tokenHash_key" ON "PasswordResetToken"("tokenHash"); CREATE INDEX "PasswordResetToken_userId_expiresAt_idx" ON "PasswordResetToken"("userId", "expiresAt");

ALTER TABLE "StudentProfile" ADD CONSTRAINT "StudentProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Module" ADD CONSTRAINT "Module_programId_fkey" FOREIGN KEY ("programId") REFERENCES "Program"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Lesson" ADD CONSTRAINT "Lesson_moduleId_fkey" FOREIGN KEY ("moduleId") REFERENCES "Module"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "StudentProgram" ADD CONSTRAINT "StudentProgram_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "StudentProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "StudentProgram" ADD CONSTRAINT "StudentProgram_programId_fkey" FOREIGN KEY ("programId") REFERENCES "Program"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LessonProgress" ADD CONSTRAINT "LessonProgress_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "StudentProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "LessonProgress" ADD CONSTRAINT "LessonProgress_lessonId_fkey" FOREIGN KEY ("lessonId") REFERENCES "Lesson"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "BodyMeasurement" ADD CONSTRAINT "BodyMeasurement_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "StudentProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "BodyMeasurement" ADD CONSTRAINT "BodyMeasurement_recordedById_fkey" FOREIGN KEY ("recordedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ProgressPhoto" ADD CONSTRAINT "ProgressPhoto_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "StudentProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Announcement" ADD CONSTRAINT "Announcement_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "AnnouncementRecipient" ADD CONSTRAINT "AnnouncementRecipient_announcementId_fkey" FOREIGN KEY ("announcementId") REFERENCES "Announcement"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AnnouncementRecipient" ADD CONSTRAINT "AnnouncementRecipient_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "StudentProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Notification" ADD CONSTRAINT "Notification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Notification" ADD CONSTRAINT "Notification_announcementId_fkey" FOREIGN KEY ("announcementId") REFERENCES "Announcement"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "RefreshToken" ADD CONSTRAINT "RefreshToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PasswordResetToken" ADD CONSTRAINT "PasswordResetToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
